package com.mfix.pos;

import android.os.Bundle;
import android.view.View;
import android.view.ViewGroup;
import android.webkit.WebView;

/** Adds a practical per-product IMEI/serial registry on top of inventory management. */
public class ProductSerialManagementPatchActivity extends InventoryManagementPatchActivity {
    private static final String PATCH =
        "(function(){if(window.__mfixSerialRegistry)return;window.__mfixSerialRegistry=true;"+
        "function esc(s){return String(s==null?'':s).replace(/[&<>\\\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\\\"':'&quot;',\"'\":'&#39;'}[c];});}"+
        "function persist(){try{if(typeof saveKey==='function'){saveKey('products',STATE.products);saveKey('misc',{returns:STATE.returns,shifts:STATE.shifts,giftCards:STATE.giftCards,preorders:STATE.preorders,auditLog:STATE.auditLog,inventoryHistory:STATE.inventoryHistory});}}catch(e){console.error(e);}}"+
        "function ensure(p){if(!Array.isArray(p.serials))p.serials=[];return p.serials;}"+
        "function draw(){var v=document.getElementById('view-inventory');if(!v)return false;var old=document.getElementById('mfixSerialRegistry');if(old)old.remove();var box=document.createElement('div');box.id='mfixSerialRegistry';box.className='card';box.style.marginTop='12px';var ps=Array.isArray(STATE.products)?STATE.products:[];var eligible=ps.filter(function(p){return Number(p.stock||0)>0||Array.isArray(p.serials)&&p.serials.length;});box.innerHTML='<div class=\\\"section-title\\\">📱 IMEI / מספר סידורי</div><div style=\\\"font-size:12px;color:var(--gray-500);margin-bottom:10px\\\">רישום מספרים ייחודיים לכל יחידה במלאי.</div><div style=\\\"display:flex;gap:8px;flex-wrap:wrap\\\"><select id=\\\"mfixSerialProduct\\\" class=\\\"input\\\" style=\\\"max-width:320px\\\"><option value=\\\"\\\">בחר מוצר</option>'+eligible.map(function(p){return '<option value=\\\"'+esc(p.id)+'\\\">'+esc(p.name||p.sku||p.id)+'</option>';}).join('')+'</select><input id=\\\"mfixSerialInput\\\" class=\\\"input\\\" style=\\\"max-width:260px\\\" placeholder=\\\"IMEI / מספר סידורי\\\"><button id=\\\"mfixSerialAdd\\\" class=\\\"btn btn-primary\\\">➕ הוסף</button></div><div id=\\\"mfixSerialList\\\" style=\\\"margin-top:10px\\\"></div>';v.insertBefore(box,v.firstChild);function list(){var id=document.getElementById('mfixSerialProduct').value;var p=ps.find(function(x){return String(x.id)===String(id);});var arr=p?ensure(p):[];document.getElementById('mfixSerialList').innerHTML=p?(arr.length?'<table class=\\\"tbl\\\"><thead><tr><th>IMEI / סידורי</th><th></th></tr></thead><tbody>'+arr.map(function(s,i){return '<tr><td>'+esc(s)+'</td><td><button class=\\\"btn btn-ghost\\\" data-mfix-serial-del=\\\"'+i+'\\\">🗑️</button></td></tr>';}).join('')+'</tbody></table>':'<div class=\\\"empty-state\\\">אין מספרים רשומים למוצר</div>'):'<div class=\\\"empty-state\\\">בחר מוצר</div>';document.querySelectorAll('[data-mfix-serial-del]').forEach(function(b){b.onclick=function(){arr.splice(Number(b.getAttribute('data-mfix-serial-del')),1);p.stock=Math.max(Number(p.stock||0),arr.length);persist();list();};});}document.getElementById('mfixSerialProduct').onchange=list;document.getElementById('mfixSerialAdd').onclick=function(){var id=document.getElementById('mfixSerialProduct').value;var val=document.getElementById('mfixSerialInput').value.trim();if(!id||!val){if(typeof toast==='function')toast('בחר מוצר והזן מספר','err');return;}var p=ps.find(function(x){return String(x.id)===String(id);});if(!p)return;var arr=ensure(p);var duplicate=ps.some(function(x){return ensure(x).some(function(s){return String(s).trim()===val;});});if(duplicate){if(typeof toast==='function')toast('המספר כבר קיים במלאי','err');return;}arr.push(val);if(Number(p.stock||0)<arr.length){var before=Number(p.stock||0);p.stock=arr.length;if(!Array.isArray(STATE.inventoryHistory))STATE.inventoryHistory=[];STATE.inventoryHistory.unshift({id:'invh_'+Date.now(),productId:p.id,type:'adjust_in',qty:arr.length-before,before:before,after:p.stock,reason:'הוספת IMEI/סידורי',at:new Date().toISOString()});}document.getElementById('mfixSerialInput').value='';persist();list();if(typeof toast==='function')toast('המספר נוסף','ok');};list();return true;}var tries=0,t=setInterval(function(){tries++;if(draw()||tries>=30)clearInterval(t);},500);console.log('[MFIX] serial registry active');})();";

    @Override protected void onCreate(Bundle savedInstanceState){
        super.onCreate(savedInstanceState);
        View root=((ViewGroup)findViewById(android.R.id.content)).getChildAt(0);
        if(root instanceof WebView)((WebView)root).postDelayed(()->((WebView)root).evaluateJavascript(PATCH,null),5000);
    }
}
